    return [6, 2, 1, 0, 0, 0, 0, 0][v]

BAD = [{3, 4, 5}, {4, 5}, {2, 5}, {1, 3, 5}, {2, 5}, {4, 5}, {2, 3, 4}]

def violations(b):
    return sum(1 for c in range(7) if b.heights[c] in BAD[c])

def opp_pair_cols(b):
    # columns whose top two stones are both the opponent's, with room above
    out = []
    for c in range(7):
        h = b.heights[c]
        if 2 <= h <= 5 and b.grid[h - 1][c] == 2 and b.grid[h - 2][c] == 2:
            out.append(c)
    return out

def fires(b):
    return len(opp_pair_cols(b)) > 0 and violations(b) == 0

def level(b):
    p = len(opp_pair_cols(b)) > 0
    v = violations(b)
    if p and v == 0:
        return 7
    if p and v == 1:
        return 3
    if v == 0:
        return 2
    return 0

def bad_cols(b):
    n = sum(1 for c in range(6) if b.heights[c] == 5)
    if b.heights[6] in (2, 3, 4):
        n += 1
    return n

def center_pair(b):
    # opponent owns the two lowest cells of the centre column
    return b.grid[0][3] == 2 and b.grid[1][3] == 2

def fires(b):
    return center_pair(b) and bad_cols(b) == 0

def level(b):
    if bad_cols(b) > 0:
        return 0
    if center_pair(b):
        return 7 if b.ply <= 12 else 4
    return 1
